class SQL:
    def __init__(self, names, columns):
        self.t = {n:{"c":columns[i],"id":1,"rows":{}} for i,n in enumerate(names)}
    def ins(self, name, row):
        t=self.t.get(name)
        if not t or len(row)!=t["c"]: return False
        t["rows"][t["id"]]=list(row); t["id"]+=1; return True
    def rmv(self, name, rowId):
        t=self.t.get(name)
        if t: t["rows"].pop(rowId,None)
    def sel(self, name, rowId, columnId):
        t=self.t.get(name)
        if not t or rowId not in t["rows"] or not (1<=columnId<=t["c"]): return "<null>"
        return t["rows"][rowId][columnId-1]
    def exp(self, name):
        t=self.t.get(name)
        if not t: return []
        return [str(i)+","+",".join(t["rows"][i]) for i in sorted(t["rows"])]

