class SQL {
    struct T{int cols,id=1;map<int,vector<string>> rows;};
    unordered_map<string,T> t;
public:
    SQL(vector<string>& names, vector<int>& columns){
        for(int i=0;i<names.size();i++) t[names[i]]={columns[i],1,{}};
    }
    bool ins(string name, vector<string> row){
        auto it=t.find(name);
        if(it==t.end()||(int)row.size()!=it->second.cols) return false;
        it->second.rows[it->second.id++]=row; return true;
    }
    void rmv(string name,int rowId){ auto it=t.find(name); if(it!=t.end()) it->second.rows.erase(rowId); }
    string sel(string name,int rowId,int col){
        auto it=t.find(name);
        if(it==t.end()||!it->second.rows.count(rowId)||col<1||col>it->second.cols) return "<null>";
        return it->second.rows[rowId][col-1];
    }
    vector<string> exp(string name){
        vector<string> res;
        auto it=t.find(name);
        if(it==t.end()) return res;
        for(auto&[id,row]:it->second.rows){string s=to_string(id);for(auto&c:row)s+=","+c;res.push_back(s);}
        return res;
    }
};

