class SQL {
    static class T{int cols,id=1;TreeMap<Integer,List<String>> rows=new TreeMap<>();}
    Map<String,T> t=new HashMap<>();
    public SQL(List<String> names, List<Integer> columns){
        for(int i=0;i<names.size();i++){T x=new T();x.cols=columns.get(i);t.put(names.get(i),x);}
    }
    public boolean ins(String name, List<String> row){
        T x=t.get(name); if(x==null||row.size()!=x.cols) return false;
        x.rows.put(x.id++,new ArrayList<>(row)); return true;
    }
    public void rmv(String name,int rowId){T x=t.get(name);if(x!=null)x.rows.remove(rowId);}
    public String sel(String name,int rowId,int col){
        T x=t.get(name);
        if(x==null||!x.rows.containsKey(rowId)||col<1||col>x.cols) return "<null>";
        return x.rows.get(rowId).get(col-1);
    }
    public List<String> exp(String name){
        List<String> res=new ArrayList<>(); T x=t.get(name);
        if(x==null) return res;
        for(var e:x.rows.entrySet()){StringBuilder sb=new StringBuilder(String.valueOf(e.getKey()));for(String c:e.getValue())sb.append(",").append(c);res.add(sb.toString());}
        return res;
    }
}

