var SQL = function(names, columns) {
    this.t = {};
    names.forEach((n,i)=>this.t[n]={cols:columns[i],nextId:1,rows:new Map()});
};
SQL.prototype.ins = function(name,row){
    const t=this.t[name]; if(!t||row.length!==t.cols) return false;
    t.rows.set(t.nextId,[...row]); t.nextId++; return true;
};
SQL.prototype.rmv = function(name,rowId){ this.t[name]?.rows.delete(rowId); };
SQL.prototype.sel = function(name,rowId,col){
    const t=this.t[name];
    if(!t||!t.rows.has(rowId)||col<1||col>t.cols) return "<null>";
    return t.rows.get(rowId)[col-1];
};
SQL.prototype.exp = function(name){
    const t=this.t[name]; if(!t) return [];
    return [...t.rows.keys()].sort((a,b)=>a-b).map(id=>id+","+t.rows.get(id).join(","));
};
